// Получаем текст из Google Script (OCR результат)
const scannedText = $json.data || $json.text || '';
const chatId = $('получаем данные о файлах').item.json.chatId;
const messageIds = $('получаем данные о файлах').item.json.allMessageIds;

if (!scannedText || scannedText.trim().length < 50) {
  return [{
    json: {
      chatId: chatId,
      error: true,
      message: '⚠️ Не удалось извлечь текст из документа. Попробуйте загрузить файл получше качеством или в другом формате.'
    }
  }];
}

return [{
  json: {
    chatId: chatId,
    documentText: scannedText,
    messageIds: messageIds,
    textLength: scannedText.length
  }
}];

const remaining = $json.remaining_analyses || 0;
const tier = $json.tier || 'free';

let message = '';

if (tier === 'free') {
  message = `❌ *Лимит исчерпан*\n\nВы использовали бесплатный анализ за этот месяц.\n\n💎 *Доступные пакеты:*\n• 5 анализов - 2990 ₸\n• 10 анализов - 4990 ₸\n• 20 анализов - 7990 ₸\n\nДля оплаты отправьте команду /pay`;
} else {
  message = `❌ *Лимит исчерпан*\n\nУ вас закончились анализы в текущем пакете.\n\nДля продолжения работы приобретите дополнительные анализы: /pay`;
}

return [{
  json: {
    chatId: $('Prepare Document Text').item.json.chatId,
    message: message,
    needsPayment: true
  }
}];

// Собираем релевантный юридический контекст
const legalContext = $input.all();
const contextText = legalContext
  .map(item => `[${item.json.category}] ${item.json.title}:\n${item.json.content}`)
  .join('\n\n---\n\n');

return [{
  json: {
    legalContext: contextText,
    contextsFound: legalContext.length
  }
}];

// Парсим JSON ответ от AI
let analysisResult;
try {
  const aiResponse = $json.message || $json.text || $json.content;
  // Извлекаем JSON из markdown если нужно
  const jsonMatch = aiResponse.match(/```json\n([\s\S]*?)\n```/) || aiResponse.match(/\{[\s\S]*\}/);
  analysisResult = JSON.parse(jsonMatch ? jsonMatch[1] || jsonMatch[0] : aiResponse);
} catch (e) {
  // Если парсинг не удался, создаем базовую структуру
  analysisResult = {
    document_type: 'unknown',
    overall_risk_score: 3,
    risk_points: [],
    summary: $json.message || 'Ошибка при анализе документа'
  };
}

const chatId = $('Set Analysis Context').item.json.chatId;
const riskScore = analysisResult.overall_risk_score || 3;

// Формируем красивое сообщение для пользователя
let userMessage = `📋 *АНАЛИЗ ДОГОВОРА ЗАВЕРШЕН*\n\n`;

// Эмодзи в зависимости от уровня риска
const riskEmoji = {
  1: '✅',
  2: '✅', 
  3: '⚠️',
  4: '🚨',
  5: '🔴'
};

userMessage += `*Общая оценка риска:* ${riskEmoji[riskScore] || '⚠️'} ${riskScore}/5\n\n`;

// Рискованные пункты
if (analysisResult.risk_points && analysisResult.risk_points.length > 0) {
  userMessage += `*🚩 ОБНАРУЖЕННЫЕ РИСКИ:*\n\n`;

  analysisResult.risk_points.forEach((risk, index) => {
    const riskEmoji = risk.risk_level >= 4 ? '🔴' : risk.risk_level >= 3 ? '⚠️' : '⚡';
    userMessage += `${index + 1}. ${riskEmoji} *${risk.issue}*\n`;

    if (risk.clause_number) {
      userMessage += `   📍 Пункт: ${risk.clause_number}\n`;
    }

    if (risk.legal_reference) {
      userMessage += `   ⚖️ Основание: ${risk.legal_reference}\n`;
    }

    if (risk.recommendation) {
      userMessage += `   💡 Рекомендация: ${risk.recommendation}\n`;
    }

    userMessage += `\n`;
  });
}

// Положительные моменты
if (analysisResult.positive_points && analysisResult.positive_points.length > 0) {
  userMessage += `*✅ ПОЛОЖИТЕЛЬНЫЕ МОМЕНТЫ:*\n`;
  analysisResult.positive_points.forEach(point => {
    userMessage += `• ${point}\n`;
  });
  userMessage += `\n`;
}

// Резюме
if (analysisResult.summary) {
  userMessage += `*📊 РЕЗЮМЕ:*\n${analysisResult.summary}\n\n`;
}

// Действия
if (analysisResult.action_items && analysisResult.action_items.length > 0) {
  userMessage += `*📝 РЕКОМЕНДУЕМЫЕ ДЕЙСТВИЯ:*\n`;
  analysisResult.action_items.forEach((action, index) => {
    userMessage += `${index + 1}. ${action}\n`;
  });
  userMessage += `\n`;
}

// Обязательный дисклеймер
userMessage += `\n⚖️ _Данный анализ носит информационный характер и не является юридической консультацией. Для принятия важных решений рекомендуем обратиться к квалифицированному юристу._\n\n`;
userMessage += `Хотите более детальный анализ? /premium`;

return [{
  json: {
    chatId: chatId,
    message: userMessage,
    analysisResult: analysisResult,
    riskScore: riskScore
  }
}];

// Подготавливаем первые 2000 символов документа для векторизации
const docText = $('Set Analysis Context').item.json.documentText;
const queryText = docText.substring(0, 2000);

return [{
  json: {
    text: queryText
  }
}];
